import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_EXCURSION, MODELO_AGENCIA, TABLA_EXCURSIONES } from '../../models/agencia-excursion.model.mjs';

export async function buscarAgenciaRepository(agenciaId) {
  const { Item } = await MODELO_AGENCIA.build(GetItemCommand)
    .key({ agenciaId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarAgenciaRepository(agenciaId, minimo) {
  const { Items = [] } = await TABLA_EXCURSIONES.build(QueryCommand)
    .entities(MODELO_EXCURSION)
    .query({ index: 'PorAgencia', partition: agenciaId })
    .options({ filters: { Excursion: { attr: 'duracionHoras', gte: minimo } } })
    .send();
  return Items;
}
